using System.Buffers.Binary;
using RiftReader2.Application;
using RiftReader2.Domain;
namespace RiftReader2.Live.Tests;
public sealed class CurrentBuildTargetPositionCandidateReaderTests
{
 const ulong M=0x140000000,Manager=0x20000000,Table=0x20010000,Bucket=0x20020000,Chain=0x20030000,Entity=0x20040000,Components=0x20050000,Health=0x20060000,Key=0x80000002CD0034D1;
 [Fact] public void Full64BitKeyUsesTaggedChain(){var s=Fixture();var result=Read(s,()=>Context(s,Key));Assert.Equal(Key,result.TargetKey);Assert.Equal(Entity,result.TargetEntity);Assert.Equal("u80000002CD0034D1",result.TargetUnitId);}
 [Fact] public void WrongHighBitsDoNotMatch(){var s=Fixture();s.Put(Chain,Node(0x10000002CD0034D1,Entity));Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,Key)));}
 [Fact] public void NoGatedTargetIsUnavailable(){var s=Fixture();var result=Read(s,()=>Context(s,null));Assert.Equal("unavailable",result.Status);Assert.Null(result.TargetVitals);}
 [Fact] public void TargetChangeFails(){var s=Fixture();int n=0;Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,++n==1?Key:Key+1)));}
 [Fact] public void ChangedNodeFails(){var s=Fixture();s.Change(Chain,Node(Key,Entity+8));Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,Key)));}
 [Fact] public void PositionUsesTargetComponent(){var s=Fixture();ConfigurePosition(s);var r=ReadPosition(s,()=>Context(s,Key));Assert.Equal("candidate",r.TargetPosition!.Status);Assert.Equal(Key,r.TargetPosition.UnitKey);Assert.Equal(1.5f,r.TargetPosition.Position!.X);}
 [Fact] public void MissingPositionPreservesVitals(){var s=Fixture();s.Put(M+0x2F588A0,BitConverter.GetBytes(1));s.Put(Entity+0x19,[255]);var r=ReadPosition(s,()=>Context(s,Key));Assert.Equal("component-unavailable",r.TargetPosition!.Status);Assert.NotNull(r.TargetVitals);}
 [Fact] public void PositionChangedTargetRejects(){var s=Fixture();ConfigurePosition(s);int n=0;Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,++n<3?Key:Key+1)));}
 [Fact] public void MissingHealthStillReturnsGuardedTargetPosition(){var s=Fixture();ConfigurePosition(s);s.Put(Entity+0x18,[255]);var r=CurrentBuildSelectedTargetCandidateReader.Read(s,_=>Context(s,Key),(_,_)=>throw new Exception("Vitals must not be read"),false,true,true);Assert.Equal("candidate",r.Status);Assert.Equal(Key,r.TargetKey);Assert.Equal(Entity,r.TargetEntity);Assert.Null(r.TargetVitals);Assert.Equal("owner-unavailable",r.TargetContext!.Status);Assert.Equal("candidate",r.TargetPosition!.Status);Assert.Equal(Key,r.TargetPosition.UnitKey);Assert.Equal(1.5f,r.TargetPosition.Position!.X);}
 [Fact] public void MissingHealthWithoutPositionStillRejects(){var s=Fixture();s.Put(Entity+0x18,[255]);Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,Key)));}
 [Fact] public void MissingHealthAndPositionDoNotSubstituteSelf(){var s=Fixture();s.Put(Entity+0x18,[255]);s.Put(M+0x2F588A0,BitConverter.GetBytes(1));s.Put(Entity+0x19,[255]);var r=ReadPosition(s,()=>Context(s,Key));Assert.Null(r.TargetVitals);Assert.Equal("component-unavailable",r.TargetPosition!.Status);Assert.Null(r.TargetPosition.Position);}
 [Fact] public void MissingHealthChangedSelectionRejects(){var s=Fixture();ConfigurePosition(s);s.Put(Entity+0x18,[255]);int n=0;Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,++n==1?Key:Key+1)));}
 [Fact] public void MissingHealthChangedNodeRejects(){var s=Fixture();ConfigurePosition(s);s.Put(Entity+0x18,[255]);s.Change(Chain,Node(Key,Entity+8));Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,Key)));}
 [Fact] public void MissingHealthChangedPositionSelectorRejects(){var s=Fixture();ConfigurePosition(s);s.Put(Entity+0x18,[255]);s.Change(Entity+0x19,[2]);Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,Key)));}
 [Fact] public void MissingHealthWrongPositionBacklinkRejects(){var s=Fixture();ConfigurePosition(s);s.Put(Entity+0x18,[255]);s.Put(0x20070010,Q(Entity+8));Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,Key)));}
 [Fact] public void PresentInvalidHealthStillRejectsWithPosition(){var s=Fixture();ConfigurePosition(s);s.Put(Health+0x10,Q(Entity+8));Assert.Throws<InvalidDataException>(()=>ReadPosition(s,()=>Context(s,Key)));}
 static SelectedTargetObservation ReadPosition(Fake s,Func<CurrentBuildPlayerContextObservation> ctx)=>CurrentBuildSelectedTargetCandidateReader.Read(s,_=>ctx(),(session,owner)=>{owner.VerifyUnchanged();return new(session.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,owner.UnitKey,new("unavailable",null),new("unavailable",null));},false,true);
 static void ConfigurePosition(Fake s){const ulong p=0x20070000;s.Put(M+0x2F588A0,BitConverter.GetBytes(1));s.Put(Entity+0x19,[1]);s.Put(Components+8,Q(p));s.Put(p+0x10,Q(Entity));var raw=new byte[0x110];BitConverter.GetBytes(1.5f).CopyTo(raw,0x48);BitConverter.GetBytes(2f).CopyTo(raw,0x4C);BitConverter.GetBytes(3f).CopyTo(raw,0x50);s.Put(p,raw);s.Put(p+0x48,raw[0x48..0x54]);}
 static SelectedTargetObservation Read(Fake s,Func<CurrentBuildPlayerContextObservation> ctx)=>CurrentBuildSelectedTargetCandidateReader.Read(s,_=>ctx(),(session,owner)=>{owner.VerifyUnchanged();return new(session.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,owner.UnitKey,new("unavailable",null),new("unavailable",null));});
 static CurrentBuildPlayerContextObservation Context(Fake s,ulong? key)=>new(s.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,123,Entity,Health,0,Health,key??0,key.HasValue?"fallback-key-candidate":"override-unavailable",key,null,65,"numeric-getter-candidate",0,"raw-byte-candidate",false);
 static Fake Fixture(){var s=new Fake();s.Put(M+0x33624A8,Q(Manager));s.Put(Manager+0x50,Q(Table));var header=new byte[24];Q(Bucket).CopyTo(header,0);Q(24).CopyTo(header,8);Q(1).CopyTo(header,16);s.Put(Table,header);var head=Node(1,Entity);Q(Chain|1).CopyTo(head,0);s.Put(Bucket,head);s.Put(Chain,Node(Key,Entity));s.Put(M+0x2F57850,BitConverter.GetBytes(0));s.Put(Entity+0x18,[0]);s.Put(Entity+0x78,Q(Components));s.Put(Components,Q(Health));s.Put(Health+0x10,Q(Entity));return s;}
 static byte[] Node(ulong k,ulong e){var b=new byte[24];Q(k).CopyTo(b,8);Q(e).CopyTo(b,16);return b;}static byte[] Q(ulong v){var b=new byte[8];BinaryPrimitives.WriteUInt64LittleEndian(b,v);return b;}
 sealed class Fake:IReadOnlyNativeMemorySession {readonly Dictionary<ulong,byte[]> data=[];readonly Dictionary<ulong,byte[]> changed=[];readonly HashSet<ulong> seen=[];public NativeProcessIdentity Identity{get;}=new(123,456,@"C:\RIFT\rift_x64.exe",CurrentBuildPlayerLookup.GameSha256,M,0x4000000);public void Put(ulong a,byte[] b)=>data[a]=b;public void Change(ulong a,byte[] b)=>changed[a]=b;public NativeReadResult Read(ulong a,int n){var b=!seen.Add(a)&&changed.TryGetValue(a,out var c)?c:data.GetValueOrDefault(a);return b is not null&&b.Length==n?new("success",b.ToArray(),null,null):new("unavailable",[],null,null);}public ValueTask<string?> RevalidateAsync(CancellationToken c)=>ValueTask.FromResult<string?>(null);public ValueTask DisposeAsync()=>ValueTask.CompletedTask;}
}
